{"rules": [
 {
  "title": "Suspicious process from web service",
  "level": "high",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "web_parent": {
    "parent_process|contains": ["http", "apache", "nginx", "www"]
   },
   "shell": {
    "process_name": ["sh", "bash", "cmd.exe", "powershell.exe"]
   },
   "condition": "web_parent AND shell"
  },
  "confidence": 0.85,
  "rationale": "Web servers spawning shells is a strong indicator of remote code execution or web shell activity."
 },
 {
  "title": "Direct connection to decoy subnet",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "decoy_zone": {
    "is_decoy": true
   },
   "condition": "decoy_zone"
  },
  "confidence": 0.95,
  "rationale": "Legitimate traffic should not be interacting with decoy assets; this indicates lateral movement or scanning."
 },
 {
  "title": "Privileged service modification",
  "level": "medium",
  "logsource": {
   "category": "service_event"
  },
  "detection": {
   "high_priv": {
    "privilege": "elevated"
   },
   "service_change": {
    "step": "modify"
   },
   "condition": "high_priv AND service_change"
  },
  "confidence": 0.7,
  "rationale": "Modifying services with elevated privileges can indicate persistence mechanisms being established."
 },
 {
  "title": "Unusual outbound connection from server",
  "level": "medium",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "server_host": {
    "host_id|contains": "server"
   },
   "non_standard_port": {
    "dst_port": [666, 1337, 31337]
   },
   "condition": "server_host AND non_standard_port"
  },
  "confidence": 0.6,
  "rationale": "Servers communicating on known 'malware' or non-standard ports suggest command and control activity."
 },
 {
  "title": "Unexpected process execution in zone",
  "level": "low",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "suspicious_proc": {
    "process_name": ["nc", "netcat", "nmap", "ncat"]
   },
   "condition": "suspicious_proc"
  },
  "confidence": 0.5,
  "rationale": "Network reconnaissance tools being executed as processes can indicate an attacker performing internal discovery."
 }
]}

{"rules": [
 {
  "title": "Unauthorized access to restricted zone",
  "level": "high",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "restricted_subnet": {
    "subnet": "restricted_zone_a"
   },
   "green_user_traffic": {
    "src_ip|contains": "green"
   },
   "condition": "restricted_subnet AND green_user_traffic"
  },
  "confidence": 0.9,
  "rationale": "Green service traffic should never attempt to cross into the restricted_zone_a subnet."
 },
 {
  "title": "Suspicious service creation",
  "level": "medium",
  "logsource": {
   "category": "service_event"
  },
  "detection": {
   "new_service": {
    "service_name|contains": "temp"
   },
   "condition": "new_service"
  },
  "confidence": 0.5,
  "rationale": "Temporary or randomly named services are often used by attackers for persistence."
 },
 {
  "title": "Unexpected process from network service",
  "level": "high",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "shell_process": {
    "process_name": ["cmd.exe", "sh", "bash", "powershell.exe"]
   },
   "network_parent": {
    "parent_process|contains": "service"
   },
   "condition": "shell_process AND network_parent"
  },
  "confidence": 0.8,
  "rationale": "Network services spawning interactive shells is a strong indicator of remote code execution."
 },
 {
  "title": "Outbound connection from server to unknown IP",
  "level": "medium",
  "logsource": {
   "category": "network_connection"
  },
  "detection": {
   "server_source": {
    "src_ip|contains": "server"
   },
   "is_decoy_hit": {
    "is_decoy": true
   },
   "condition": "server_source AND is_decoy_hit"
  },
  "confidence": 0.7,
  "rationale": "Servers interacting with decoy assets indicates lateral movement or scanning."
 },
 {
  "title": "Privileged process creation on server",
  "level": "high",
  "logsource": {
   "category": "process_creation"
  },
  "detection": {
   "high_priv": {
    "privilege": "elevated"
   },
   "server_host": {
    "host_id|contains": "server"
   },
   "condition": "high_priv AND server_host"
  },
  "confidence": 0.6,
  "rationale": "Unexpected elevated processes on critical server hosts can indicate privilege escalation."
 }
]}

